sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float speed;
uniform float angle;
uniform float accel;
uniform float wrap;
uniform float gapBetween;
uniform float shutter;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float4 shot(float2 coord, float T) {
    float2 dir = float2(cos(radians(angle)), sin(radians(angle)));
    float off = speed * T * (1.0 + 0.5 * accel * T);
    float2 q = coord - dir * off;
    if (wrap > 0.5) {
        float2 wsz = size + float2(gapBetween);
        float2 w = mod(q, wsz);
        float inside = step(w.x, size.x) * step(w.y, size.y);
        return texT(w) * inside;
    }
    return texT(q);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 acc = float4(0.0);
    for (int i = 0; i < 8; i++) {
        acc += shot(coord, time - shutter * 0.04 * float(i) / 7.0);
    }
    return fin(c, acc / 8.0, opacity);
}
